package com.fuelflex.platform.operations.service;import java.math.*;import java.time.OffsetDateTime;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import com.fuelflex.platform.common.exception.*;import com.fuelflex.platform.operations.entity.*;import com.fuelflex.platform.operations.repository.*;import com.fuelflex.platform.sale.service.*;import lombok.RequiredArgsConstructor;
@Service@RequiredArgsConstructor@Transactional public class ShiftReconciliationService{private final ShiftReconciliationRepository reconciliations;private final TankReturnRepository tankReturns;private final InternalConsumptionRepository internals;private final PosConfigurationResolver pricing;
 public ShiftReconciliation calculate(PumpShiftAssignment shift,BigDecimal requestedCredit){if(shift.getClosingIndex()==null||shift.getOpeningIndex()==null)throw new BusinessException("Les index de l’affectation sont requis pour le rapprochement.");BigDecimal metered=s(shift.getClosingIndex().subtract(shift.getOpeningIndex())),returned=s(tankReturns.sumQuantityByShiftId(shift.getId())),internal=s(internals.sumQuantityByShiftId(shift.getId())),credit=s(requestedCredit);if(returned.signum()<0||internal.signum()<0)throw new BusinessException("Les volumes non commerciaux ne peuvent pas être négatifs.");BigDecimal saleable=s(metered.subtract(returned).subtract(internal));if(saleable.signum()<0)throw new BusinessException("Les remises en cuve et consommations internes dépassent la sortie compteur.");if(credit.signum()<0||credit.compareTo(saleable)>0)throw new BusinessException("La quantité crédit dépasse le volume commercialisable de "+saleable.toPlainString()+" L.");BigDecimal cash=s(saleable.subtract(credit));ResolvedPosContext cashContext=pricing.resolve(shift),creditContext=pricing.resolveCredit(shift),internalContext=pricing.resolveInternal(shift);if(!same(cashContext,creditContext)||!same(cashContext,internalContext))throw new ConflictException("Les tarifs CASH, CREDIT et INTERNAL ne résolvent pas la même configuration physique.");BigDecimal cashAmount=amount(cash,cashContext.unitPrice()),creditAmount=amount(credit,creditContext.unitPrice()),internalAmount=amount(internal,internalContext.unitPrice());ShiftReconciliation r=reconciliations.findByShiftAssignmentId(shift.getId()).orElseGet(ShiftReconciliation::new);r.setShiftAssignment(shift);r.setOpeningIndex(s(shift.getOpeningIndex()));r.setClosingIndex(s(shift.getClosingIndex()));r.setMeteredVolume(metered);r.setCashVolume(cash);r.setCreditVolume(credit);r.setTankReturnVolume(returned);r.setInternalConsumptionVolume(internal);r.setInternalUnitPrice(s(internalContext.unitPrice()));r.setInternalConsumptionAmount(internalAmount);r.setTotalSoldVolume(s(cash.add(credit)));r.setAccountedVolume(s(cash.add(credit).add(returned).add(internal)));r.setVolumeVariance(s(metered.subtract(r.getAccountedVolume())));r.setSourceTank(cashContext.tank());r.setProduct(cashContext.product());r.setCashUnitPrice(s(cashContext.unitPrice()));r.setCreditUnitPrice(s(creditContext.unitPrice()));r.setCashAmount(cashAmount);r.setCreditAmount(creditAmount);r.setTurnover(amount(cashAmount.add(creditAmount)));r.setCalculatedAt(OffsetDateTime.now());return reconciliations.save(r);}
 public ShiftReconciliation calculate(PumpShiftAssignment shift){return reconciliations.findByShiftAssignmentId(shift.getId()).orElseThrow(()->new ConflictException("Le rapprochement définitif de l’affectation est introuvable."));}private boolean same(ResolvedPosContext a,ResolvedPosContext b){return a.tank().getId().equals(b.tank().getId())&&a.product().getId().equals(b.product().getId());}private BigDecimal s(BigDecimal v){if(v==null)throw new BusinessException("La quantité est requise.");try{return v.setScale(3,RoundingMode.UNNECESSARY);}catch(ArithmeticException e){throw new BusinessException("Les volumes acceptent au maximum trois décimales.");}}private BigDecimal amount(BigDecimal v){return v.setScale(3,RoundingMode.HALF_UP);}private BigDecimal amount(BigDecimal q,BigDecimal p){return q.multiply(p).setScale(3,RoundingMode.HALF_UP);}}
